const tutorialCard = (t: typeof tutorials[number], i: number) => `<article id="${t.id}" class="tutorial-lesson"><p class="eyebrow">Tutorial ${i + 1}</p><h2>${t.title}</h2><p><strong>Goal:</strong> ${t.goal}</p><p><strong>Best for:</strong> ${t.audience}</p>${visualWalkthrough(t)}${narrationPlayer(t)}${i < 3 ? `<video controls playsinline preload="metadata" aria-label="${t.title}" poster="/website/chart-desktop.png"><source src="/website/videos/${t.id}.mp4" type="video/mp4"><track default kind="captions" srclang="en" label="English" src="/website/videos/${t.id}.vtt"></video><p><a href="/website/videos/${t.id}.mp4" download>Download MP4</a> · <a href="/website/videos/${t.id}.vtt" download>Download subtitles</a></p>` : `<div class="notice"><strong>Visual and audio tutorial included.</strong> Use the app walkthrough above to see what to do, then use audio narration or the script below to follow along.</div>`}<details open><summary>Step-by-step lesson</summary><ol>${t.steps.map(s => `<li>${s}</li>`).join("")}</ol></details><details><summary>Female narration script</summary>${t.script.map(line => `<p>${line}</p>`).join("")}</details><details><summary>Subtitle text</summary><ol>${t.script.map(line => `<li>${line}</li>`).join("")}</ol></details><p><a class="button secondary" href="/website/tutorials/${t.id}/">Open the full tutorial page</a></p></article>`;
const tutorialDetailPage = (t: typeof tutorials[number]) => `${heading("KinForge tutorial", t.title, t.goal)}<section class="wrap section prose tutorial-lesson">${narrationNote}${visualWalkthrough(t)}${narrationPlayer(t)}<h2>Who this lesson is for</h2><p>${t.audience}</p><h2>Before you start</h2><p>Use fictional demo data while learning. Move to real family, case, historical, or creative work only after you understand the controls, privacy choices, and export rules.</p><h2>Step-by-step walkthrough</h2><ol>${t.steps.map(s => `<li>${s}</li>`).join("")}</ol><h2>Realistic female narration script</h2>${t.script.map(line => `<p>${line}</p>`).join("")}<h2>Subtitle text</h2><ol>${t.script.map(line => `<li>${line}</li>`).join("")}</ol><h2>Practice task</h2><p>Repeat the lesson with a small fictional example first. Then try it again with your own project only after exporting a backup.</p><p><a class="button" href="/website/tutorials/">Back to all tutorials</a></p></section>`;
const tutorialPage = `${heading("KinForge tutorials", "Learn every core feature step by step", "Detailed walkthroughs for creating trees, organizing projects, editing profiles, reports, exports, special access, fiction/RPG workflows, privacy, sharing and backups.")}<section class="wrap section tutorials">${narrationNote}<div class="feature-columns">${tutorials.map(t => `<article><h2>${t.title}</h2><p>${t.goal}</p><a href="/website/tutorials/${t.id}/">Open lesson</a></article>`).join("")}</div>${tutorials.map(tutorialCard).join("")}</section>`;
const freeAccess = `${heading("Free trial", "Start with four days of simplified KinForge access", "The free trial gives new users a lower-capacity, simplified version of the core KinForge workflow before they decide whether to upgrade to Suite or request special access.")}<section class="wrap section prose">${exportTerms}<h2>What the Free tier includes</h2><p>Free access is for trying KinForge first. It includes the separate demo, simplified relationship maps, basic profiles, basic reports, basic exports, and a lower-quality/lower-capacity version of the core feature set.</p><p>After four days, users decide whether to choose a KinForge Genealogy Studio Suite plan or request special access. Exported and downloaded files still keep KinForge credit and Dreams of Serene Landscapes copyright.</p><p><a class="button" href="/downloads/trial">Download the free trial</a></p>${appDescription}</section>`;
const suiteAccess = `${heading("KinForge Genealogy Studio Suite", "Paid access for fuller KinForge features", "Suite is the paid version of KinForge, with Basic, Plus, Premium, and Pro options that can be offered weekly, monthly, or yearly.")}<section class="wrap section prose">${exportTerms}${planSummary}<h2>Why Suite supports the project</h2><p>Suite subscriptions help Dreams of Serene Landscapes keep improving KinForge, maintain public resources, build tutorials, support accessibility work, and keep the app more affordable than tools that feel too limited or overpriced.</p><p><a class="button" href="/downloads/paid">Open Suite downloads</a></p>${appDescription}</section>`;
const gettingStarted = `${heading("Getting started", "Your first relationship map", "Try the separate demo before adding your own family research, case map, story world, campaign, or historical project.")}<section class="wrap section prose">${exportTerms}<h2>1. Start free</h2><p><a href="/">Open KinForge</a> and choose <strong>Get started free</strong> for the 4-day trial/demo flow. Trial access is simplified and lower quality than paid or approved KinForge Genealogy Special Access Edition.</p><h2>2. Create your account</h2><p>Choose Create account when you are ready to keep a private cloud library. New accounts must click I accept for both the KinForge Privacy Policy and Terms &amp; Conditions first. Sign in with the same KinForge account on each device to access its cloud library.</p><h2>3. Choose what happens after four days</h2><p>After the trial, choose a Suite plan or request special access through support. Special Access Edition requests are reviewed and may require real, non-AI proof for close or special users.</p><h2>4. Organize your work</h2><p>In Library, create a book, a collection inside it, and a subcollection for your trees, genograms, casts, campaigns, cases, or archives.</p><h2>5. Build the network</h2><p>Open a tree and add a person. Add parents, guardians, partners, children, allies, rivals, or other important relationships. Select a card for its person overview.</p><h2>6. Keep a backup</h2><p>Export backups before substantial edits or experiments. Review reports before sharing, particularly when they contain sensitive information about real people.</p><h2>Copyright and downloads</h2><p>GEDCOM, Word/RTF-style documents, PDFs, HTML, JSON backups, CSV and other downloads keep the KinForge/Dreams copyright and credit across free trials, KinForge Genealogy Studio Suite, beta access, and KinForge Genealogy Special Access Edition.</p><h2>Mac and Windows</h2><p><a href="/downloads">Choose your computer's download</a>. On a Mac, Apple menu &rarr; About This Mac identifies Apple Silicon or Intel. Current Mac packages are not Apple-notarized; Windows packages are not publisher-signed.</p><h2>iPhone and iPad</h2><p>Open the web app in Safari. Use Share, then Add to Home Screen. Sign in with the same KinForge account. Keep a network connection for cloud sync.</p><a class="button" href="/website/tutorials/">Watch the tutorials</a></section>`;
const beta = `${heading("KinForge beta program", "Help shape the next chapter", "Register with a KinForge account to express interest in future releases. Start with a 4-day trial, then choose a Suite plan or request special access.")}<section class="wrap section beta-layout"><div><h2>Plans, discounts, beta, and special access</h2><p>Start with a 4-day free trial, choose a Suite plan when ready, or request special access through support. Stripe checkout can be connected for paid plans when the plan buttons are wired to your live products.</p>${exportTerms}${planSummary}<h3>Before you join</h3><ul><li>Beta software can contain bugs. No app can guarantee zero crashes or data loss.</li><li>Use a separate beta sandbox and a copy of your work, not your only copy.</li><li>The free trial lasts 4 days and uses simplified, lower-quality access to core features.</li><li>KinForge Genealogy Studio Suite unlocks more workspace capacity and fuller app features, with weekly, monthly, and yearly payment options.</li><li>KinForge Genealogy Special Access Edition requires approval and a code.</li><li>Creating an account signs the user up for monthly KinForge newsletters, app updates, new-feature notes, and release emails.</li><li>Exports and downloads from the app must follow the KinForge copyright terms.</li></ul><a href="/website/privacy-policy/">Privacy Policy</a> &middot; <a href="/website/terms/">Terms &amp; Conditions</a></div><section class="signup-panel" id="register" aria-labelledby="signup-title"><h2 id="signup-title">Register your interest</h2><p id="account-status" role="status">Checking sign-in status...</p><form id="beta-auth"><label>Account action<select name="action"><option value="register">Create a KinForge account</option><option value="login">Sign in to an existing account</option></select></label><label>Name<input name="name" autocomplete="name" maxlength="100"></label><label>I am using KinForge as<select name="userType"><option>Writer</option><option>DND player</option><option>Historian</option><option>Roleplayer</option><option>RPG player</option><option>Genealogist</option><option>Social worker</option><option>Student</option><option>Nonprofit</option><option>Educator</option><option>Other</option></select></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><p class="muted">Use 12 or more characters. <a href="/">Forgot your password?</a></p><label class="check"><input name="privacyAccepted" type="checkbox" required>I accept and agree to follow the KinForge Privacy Policy.</label><label class="check"><input name="termsAccepted" type="checkbox" required>I accept and agree to follow the KinForge Terms &amp; Conditions, including copyright, account, export, download, and monthly newsletter/update email rules.</label><p class="muted">Need Special Access Edition before using KinForge? <a href="/website/support/">Request special access with proof first.</a></p><button type="submit">Continue</button></form><section id="recovery" hidden><h3>Keep your recovery key safe</h3><p>This key can recover your account. Do not share it.</p><code id="recovery-key"></code><button id="save-recovery" type="button">Download recovery key</button></section><form id="beta-register" hidden><input name="plan" type="hidden" value="beta"><input name="interval" type="hidden" value="month"><p>Register interest in the beta version for this KinForge account.</p><label class="check"><input name="consent" type="checkbox" required>I understand beta access, trials, subscriptions, exports, downloads, and monthly KinForge newsletters must follow the KinForge copyright terms.</label><button type="submit">View plans and beta access</button></form><p id="beta-result" role="status" aria-live="polite"></p><button id="withdraw-interest" type="button" hidden>Withdraw interest</button><noscript><p>JavaScript is needed for registration. Public pages and downloads remain available.</p></noscript></section></section>`;
const newsletter = `${heading("KinForge newsletter", "Monthly app updates and new-feature notes", "Sign up for monthly KinForge emails about app updates, new features, beta news, download notices, tutorials, and Suite announcements.")}<section class="wrap section beta-layout"><div class="prose"><h2>What subscribers receive</h2><ul><li>Monthly KinForge app update notes.</li><li>New feature announcements and tutorial links.</li><li>Beta program reminders and safer testing guidance.</li><li>Download, Suite, discount, and special-access notices when relevant.</li></ul><p>Creating a KinForge account also signs the user up for monthly KinForge newsletters and app-update emails.</p><p>Newsletter requests are sent through the support intake so Dreams of Serene Landscapes can keep a record of who asked to receive updates.</p></div><section class="signup-panel" aria-labelledby="newsletter-title"><h2 id="newsletter-title">Sign up for the newsletter</h2><form id="public-newsletter"><input type="hidden" name="type" value="Newsletter signup"><input type="hidden" name="subject" value="Newsletter signup"><input type="hidden" name="message" value="Please add this email to the monthly KinForge newsletter and app-update list."><label>Name<input name="name" autocomplete="name" maxlength="100"></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>I am using KinForge as<select name="userType"><option>Writer</option><option>DND player</option><option>Historian</option><option>Roleplayer</option><option>RPG player</option><option>Genealogist</option><option>Social worker</option><option>Student</option><option>Nonprofit</option><option>Educator</option><option>Other</option></select></label><label class="check"><input name="permissionToReply" type="checkbox" checked required>I agree to receive monthly KinForge newsletters, app updates, new-feature notes, and release emails.</label><button type="submit">Sign up</button></form><p id="newsletter-result" role="status" aria-live="polite"></p></section></section>`;
const contribute = `${heading("Contribute & Help Our Cause", "Help improve KinForge", "Send feature ideas, feedback, accessibility suggestions, bug reports, tutorial requests, and feature-addition proposals for the free app, Suite, public website, and Special Access Edition.")}<section class="wrap section beta-layout"><div class="prose">${exportTerms}<h2>What to send</h2><p>Use this page to help Dreams of Serene Landscapes improve KinForge for families, social workers, writers, genealogists, historians, roleplayers, RPG players, educators, students, nonprofits, and other users.</p><div class="value-grid">${iconCard("F", "Feature ideas", "Suggest new tools, reports, exports, relationship types, accessibility options, tutorial topics, or workflow improvements.")}${iconCard("B", "Bug reports", "Describe what happened, what you expected, what you clicked, and which app or website version you used.")}${iconCard("A", "Accessibility help", "Share access needs, disability support ideas, language issues, screen-reader concerns, or clearer learning paths.")}${iconCard("S", "Special Access feedback", "Explain what approved no-cost Special Access users need while keeping credit and copyright rules intact.")}</div><h2>How this helps</h2><p>Contributions help prioritize the monthly update plan, improve tutorials, make the free trial clearer, shape KinForge Genealogy Studio Suite, and keep the Special Access Edition useful for approved users.</p></div><section class="signup-panel" aria-labelledby="contribute-title"><h2 id="contribute-title">Contribution form</h2><form id="public-support"><input type="hidden" name="type" value="Feature request / feedback"><label>Name<input name="name" autocomplete="name" maxlength="100"></label><label>Email for replies<input name="email" type="email" autocomplete="email" required></label><label>I am using KinForge as<select name="treeTitle"><option>Writer</option><option>DND player</option><option>Historian</option><option>Roleplayer</option><option>RPG player</option><option>Genealogist</option><option>Social worker</option><option>Student</option><option>Nonprofit</option><option>Educator</option><option>Family historian</option><option>Other</option></select></label><label>Contribution type<select name="subject"><option>New feature suggestion</option><option>Feature addition request</option><option>Feedback about an existing feature</option><option>Bug report</option><option>Accessibility suggestion</option><option>Tutorial request</option><option>Website or download page feedback</option><option>Special Access Edition feedback</option><option>Pricing, plan, or discount feedback</option><option>Other KinForge improvement</option></select></label><label>Device, app, or website version<input name="device" maxlength="500" placeholder="Example: public website, free trial, Suite app, Special Access Edition, Mac app 1.3.8, Windows app"></label><label>Feature, feedback, or suggestion<textarea name="message" rows="8" placeholder="Describe the idea, why it matters, who it helps, and what would make KinForge better." required></textarea></label><label>Links, proof, screenshots, or extra context<textarea name="proof" rows="4" placeholder="Optional: links, screenshot descriptions, examples, accessibility context, or extra notes. Do not paste passwords, recovery codes, or private records."></textarea></label><label class="check"><input name="permissionToReply" type="checkbox" checked>Allow support to reply to this email</label><button type="submit">Send contribution</button></form><p id="support-result" role="status" aria-live="polite"></p></section></section>`;
const releases = `${heading("Releases & updates", `KinForge ${release.version}`, "The current desktop preview for Apple Silicon, Intel and Windows. Your library is separate from your installed app version.")}<section class="wrap section prose"><article><p class="eyebrow">Current desktop release</p><h2>Version 1.3.8</h2><ul><li>Top-bar app language selection, separate from tree language.</li><li>Beta sandbox controls for trying changes in a separate local copy.</li><li>Apple Silicon, Intel and Windows packages.</li></ul><a class="button" href="/downloads">Download 1.3.8</a></article><article><p class="eyebrow">Website update</p><h2>A home for KinForge</h2><p>Use-case pages for social workers, writers, genealogists, historians, roleplayers, RPG players and relationship-rich projects, plus tutorial videos, official app downloads, beta interest registration and public export credit guidance.</p><p>These website changes do not mean the existing desktop installers have been rebuilt.</p></article><h2>Updating an installation</h2><p>Use the in-app Update Agent to check published packages. An already-current version should not need reinstalling. Export a backup before installing a beta or making major changes.</p><h2>Try the beta safely</h2><p>The available installers include the separate guest demo. Beta interest uses a KinForge account and does not collect payment on this website.</p></section>`;
const privacy = `${heading("Privacy & beta safety", "Your work stays yours", "Use fictional demo data to explore. Treat real family, medical and identity records with care.")}<section class="wrap section prose"><h2>Accounts and libraries</h2><p>KinForge uses separate email-and-password accounts. Signing in identifies your cloud library. Sharing is an explicit choice; the guest demo is not a shared-account login.</p><h2>Account terms</h2><p>New accounts must agree to KinForge copyright, export and download terms. Free trials, KinForge Genealogy Studio Suite, beta access, and KinForge Genealogy Special Access Edition keep the KinForge/Dreams copyright and credit. Special Access Edition requests are reviewed through support before account creation or use.</p><h2>Interest registration</h2><p>Your beta interest and registration time are stored with your account. No card data is collected here. Withdraw your interest on the beta page while signed in.</p><h2>Special Access Edition proof</h2><p>Only approved close or special people may receive special access or extra written permission. They must provide real, non-AI proof through support, such as photos together or other digital or physical records. Approval is not automatic, and KinForge/Dreams copyright and credit still apply unless written permission says otherwise.</p><h2>Beta safety</h2><p>Experimental releases may fail. Use a sandbox, keep independent backups and test before changing important work. Zero data loss cannot be guaranteed.</p><h2>Public website</h2><p>Public pages do not expose your trees or account contents. This update adds no advertising trackers or analytics cookies. Hosting providers may still process technical logs.</p><h2>Questions</h2><p><a href="/website/support/">Open the permission and support form</a>.</p></section>`;
const privacyPolicy = `${heading("Privacy Policy", "How KinForge handles information", `Effective ${LEGAL_EFFECTIVE_DATE}. This policy applies to the app, website, beta, accounts, support forms, exports and downloads.`)}<section class="wrap section prose">${legalSections(PRIVACY_POLICY_SECTIONS)}<p><a href="/website/support/">Contact support about privacy</a>.</p></section>`;
const termsConditions = `${heading("Terms & Conditions", "Rules for using KinForge", `Effective ${LEGAL_EFFECTIVE_DATE}. These terms apply before using the app, creating an account, trying the demo, checking updates, exporting, or downloading files.`)}<section class="wrap section prose">${legalSections(TERMS_CONDITIONS_SECTIONS)}<p><a href="/website/support/">Request permission or ask a question</a>.</p></section>`;
const specialAccess = `${heading("KinForge Genealogy Special Access Edition", "Approved no-cost edition access with credit and copyright rules", "KinForge Genealogy Special Access Edition is for approved close people and approved FOP-style requests. It still keeps KinForge credit and Dreams of Serene Landscapes copyright on the app, downloads, documents, and exports.")}<section class="wrap section prose">${exportTerms}<h2>How Special Access Edition works</h2><p>Special Access Edition requests are reviewed through the support form or through an approved Dreams of Serene Landscapes email request. It is not automatic. Approved users may receive KinForge Genealogy Special Access Edition, but they still need to credit KinForge and Dreams of Serene Landscapes when asked, and exported files keep the required copyright notice.</p><h2>Proof and approval</h2><p>Close or special people may need real, non-AI proof, such as photos together, shared records, or other digital or physical proof. FOP-style requests should explain who is requesting access, why KinForge Genealogy Special Access Edition is appropriate, and how the app will be used.</p>${appDescription}<p><a class="button" href="/website/support/">Request special access</a> <a class="button secondary" href="/downloads/special-access">Enter special access code</a></p></section>`;
const support = `${heading("Support & special access", "Request KinForge Genealogy Special Access Edition", "Use this form for support, beta questions, or a special-access request before creating an account.")}<section class="wrap section beta-layout"><div>${exportTerms}<h2>Proof requirements</h2><p>For special access, explain why you are close to Dreams of Serene Landscapes or why your situation should be reviewed, and provide real proof when requested. Proof can include non-AI photos together, a link to shared records, or a description of physical or digital evidence you can provide. Do not upload private identity documents into this public form.</p><p>Approval is not automatic. Free trials, paid Suite access, beta access, and approved KinForge Genealogy Special Access Edition all keep the KinForge copyright and credit on exports and downloads.</p><p><a href="/website/special-access/">Read the Special Access mission, founding story, vision, and values</a>.</p></div><section class="signup-panel" aria-labelledby="support-title"><h2 id="support-title">Support form</h2><form id="public-support"><label>Name<input name="name" autocomplete="name" maxlength="100"></label><label>Email for replies<input name="email" type="email" autocomplete="email" required></label><label>Request type<select name="type"><option>Special access request</option><option>Support request</option><option>Account or login help</option><option>Download question</option><option>Bug report</option></select></label><label>Subject<input name="subject" maxlength="160" value="Special access request"></label><label>Proof description or link<textarea name="proof" rows="5" placeholder="Describe or link real non-AI proof, such as photos together or other digital/physical records." required></textarea></label><label>Message<textarea name="message" rows="6" placeholder="Explain what access you are asking for and how the export or download will be used." required></textarea></label><label class="check"><input name="permissionToReply" type="checkbox" checked>Allow support to reply to this email</label><button type="submit">Send request</button></form><p id="support-result" role="status" aria-live="polite"></p></section></section>`;
