export function publicWebsiteRoutes(request: Request): Response | null {
  const path = new URL(request.url).pathname;
  if (!["GET", "HEAD"].includes(request.method)) return null;
  if (path === "/website/pricing" || path === "/website/pricing/") return new Response(null, { status: 308, headers: { Location: "/website/beta/" } });
  const canonical = path === "/website/index.html" || path === "/website" ? "/website/" : `${path}/`;
  if (!pages[path] && pages[canonical]) return new Response(null, { status: 308, headers: { Location: canonical } });
  if (pages[path]) return websiteResponse(request, path, ...pages[path]);
  if (path === "/robots.txt") return new Response(request.method === "HEAD" ? null : `User-agent: *\nAllow: /website/\nAllow: /downloads\nDisallow: /api/\nSitemap: ${siteOrigin}/sitemap.xml\n`, { headers: { "Content-Type": "text/plain; charset=utf-8" } });
  if (path === "/sitemap.xml") return new Response(request.method === "HEAD" ? null : `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${publicPaths.map(p => `<url><loc>${siteOrigin}${p}</loc></url>`).join("")}</urlset>`, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
  return null;
}
